<body>
  <div class="container">
    <h1>أدخل الرمز</h1>
    <p>أرسلنا رمزًا مكوّن من 6 أرقام إلى +966 55 123 4567</p>
    <div class="code-inputs">
      <input type="text" maxlength="1" inputmode="numeric" pattern="[0-9]">
      <input type="text" maxlength="1" inputmode="numeric" pattern="[0-9]">
      <input type="text" maxlength="1" inputmode="numeric" pattern="[0-9]">
      <input type="text" maxlength="1" inputmode="numeric" pattern="[0-9]">
      <input type="text" maxlength="1" inputmode="numeric" pattern="[0-9]">
      <input type="text" maxlength="1" inputmode="numeric" pattern="[0-9]">
    </div>
    <div id="countdown">إعادة الإرسال بعد 0:45</div>
    <button id="verify">التحقق</button>
  </div>

  <script>
    const inputs = document.querySelectorAll('.code-inputs input');
    const countdownEl = document.getElementById('countdown');
    const verifyBtn = document.getElementById('verify');

    // Focus first input
    inputs[0].focus();

    // Auto move to next input
    inputs.forEach((input, index) => {
      input.addEventListener('input', () => {
        if (input.value.length === 1) {
          if (index < inputs.length - 1) {
            inputs[index + 1].focus();
          }
        }
      });
    });

    // Countdown timer
    let time = 45;
    function updateCountdown() {
      const minutes = Math.floor(time / 60);
      const seconds = time % 60;
      countdownEl.textContent = `إعادة الإرسال بعد ${minutes}:${seconds.toString().padStart(2, '0')}`;
      if (time > 0) {
        time--;
        setTimeout(updateCountdown, 1000);
      } else {
        countdownEl.textContent = 'أعد الإرسال';
      }
    }
    updateCountdown();

    // Verify button handler
    verifyBtn.addEventListener('click', () => {
      const code = Array.from(inputs).map(i => i.value).join('');
      if (/^\d{6}$/.test(code)) {
        alert('تم إرسال الرمز: ' + code);
      } else {
        alert('يرجى إدخال الرمز الكامل المكوّن من 6 أرقام');
      }
    });
  </script>
